<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Csrf;use App\Core\Database;use App\Services\JudgeDirectoryService;
$pdo=Database::connection();JudgeDirectoryService::ensureProfileRequests($pdo);$error='';$success='';
$cleanList=static function(mixed $value,array $allowed):string{$values=is_array($value)?$value:[];return implode(',',array_values(array_intersect($allowed,array_map('strval',$values))));};
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null))$error='Please refresh the page and try again.';
 elseif(trim((string)($_POST['website']??''))!=='')$success='Profile submitted for organiser approval.';
 else{
  $name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));
  if($name==='')$error='Full name is required.';elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email or leave it blank.';
  else{
   $photo=null;
   if(!empty($_FILES['photo']['tmp_name'])){$file=$_FILES['photo'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime])||(int)$file['size']>5*1024*1024)$error='Photo must be JPG, PNG or WebP and under 5 MB.';else{$dir=dirname(__DIR__).'/uploads/judges';if(!is_dir($dir)&&!mkdir($dir,0755,true))$error='Photo upload is temporarily unavailable.';else{$filename='profile-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename))$error='Photo upload failed.';else$photo=url('uploads/judges/'.$filename);}}}
   if($error===''){$preferred=in_array(($_POST['preferred_contact']??''),['email','whatsapp','either','none'],true)?$_POST['preferred_contact']:'none';$role=in_array(($_POST['judge_role']??''),['regular','chief','both'],true)?$_POST['judge_role']:'regular';$pdo->prepare("INSERT INTO bdc_judge_profile_requests(full_name,display_name,country,city,photo_url,instagram,email,phone,whatsapp,preferred_contact,dance_styles,judge_role,qualified_divisions,qualified_rounds,languages,biography,experience,certification) VALUES(:name,:display,:country,:city,:photo,:instagram,:email,:phone,:whatsapp,:preferred,:styles,:role,:divisions,:rounds,:languages,:biography,:experience,:certification)")->execute(['name'=>$name,'display'=>trim((string)($_POST['display_name']??''))?:null,'country'=>trim((string)($_POST['country']??''))?:null,'city'=>trim((string)($_POST['city']??''))?:null,'photo'=>$photo,'instagram'=>ltrim(trim((string)($_POST['instagram']??'')),'@')?:null,'email'=>$email?:null,'phone'=>trim((string)($_POST['phone']??''))?:null,'whatsapp'=>trim((string)($_POST['whatsapp']??''))?:null,'preferred'=>$preferred,'styles'=>$cleanList($_POST['dance_styles']??[],['bachata','salsa'])?:null,'role'=>$role,'divisions'=>$cleanList($_POST['qualified_divisions']??[],['novice','intermediate','advanced','bachata_rising','bachata_open','bachata_invitational','salsa_rising','salsa_open','semi_pro','pro','all_star'])?:null,'rounds'=>$cleanList($_POST['qualified_rounds']??[],['heats','semifinal','final'])?:null,'languages'=>trim((string)($_POST['languages']??''))?:null,'biography'=>trim((string)($_POST['biography']??''))?:null,'experience'=>trim((string)($_POST['experience']??''))?:null,'certification'=>trim((string)($_POST['certification']??''))?:null]);$success='Your judge profile was submitted for organiser approval.';$_POST=[];}
  }
 }
}
function checked(string $group,string $value):string{return in_array($value,(array)($_POST[$group]??[]),true)?' checked':'';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Judge Profile</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:900px"><div class="mb-4"><h1 class="h2 mb-1">BDC Judge Profile</h1><p class="text-muted mb-0">Submit your judging profile for organiser approval.</p></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card border-0 shadow-sm"><div class="card-body p-4"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><div class="d-none"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="full_name" value="<?=e((string)($_POST['full_name']??''))?>" required></div><div class="col-md-6"><label class="form-label">Display name</label><input class="form-control" name="display_name" value="<?=e((string)($_POST['display_name']??''))?>"></div><div class="col-md-6"><label class="form-label">Country</label><input class="form-control" name="country" value="<?=e((string)($_POST['country']??''))?>"></div><div class="col-md-6"><label class="form-label">City</label><input class="form-control" name="city" value="<?=e((string)($_POST['city']??''))?>"></div><div class="col-md-6"><label class="form-label">Instagram</label><input class="form-control" name="instagram" value="<?=e((string)($_POST['instagram']??''))?>" placeholder="@handle"></div><div class="col-md-6"><label class="form-label">Profile photo</label><input class="form-control" type="file" name="photo" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><hr><h2 class="h5">Private contact details</h2></div><div class="col-md-4"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=e((string)($_POST['email']??''))?>"></div><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e((string)($_POST['phone']??''))?>"></div><div class="col-md-4"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp" value="<?=e((string)($_POST['whatsapp']??''))?>"></div><div class="col-md-6"><label class="form-label">Preferred contact</label><select class="form-select" name="preferred_contact"><option value="none">No preference</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="either">Either</option></select></div><div class="col-12"><hr><h2 class="h5">Judging profile</h2></div><div class="col-md-6"><label class="form-label d-block">Dance styles</label><?php foreach(['bachata'=>'Bachata','salsa'=>'Salsa'] as $v=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dance_styles[]" value="<?=$v?>"<?=checked('dance_styles',$v)?>> <span class="form-check-label"><?=$label?></span></label><?php endforeach;?></div><div class="col-md-6"><label class="form-label">Judge role</label><select class="form-select" name="judge_role"><option value="regular">Regular Judge</option><option value="chief">Chief Judge</option><option value="both">Regular and Chief Judge</option></select></div><div class="col-12"><label class="form-label d-block">Qualified rounds</label><?php foreach(['heats'=>'Heats','semifinal'=>'Semifinal','final'=>'Final Relative Placement'] as $v=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="qualified_rounds[]" value="<?=$v?>"<?=checked('qualified_rounds',$v)?>> <span class="form-check-label"><?=$label?></span></label><?php endforeach;?></div><div class="col-12"><label class="form-label d-block">Qualified divisions</label><div class="row g-2"><?php foreach(['novice'=>'Novice','intermediate'=>'Intermediate','advanced'=>'Advanced','bachata_rising'=>'Bachata Rising','bachata_open'=>'BDC Open','bachata_invitational'=>'Bachata Invitational','salsa_rising'=>'Salsa Rising','salsa_open'=>'Salsa Open','semi_pro'=>'Semi Pro','pro'=>'Pro','all_star'=>'All Star'] as $v=>$label):?><div class="col-6 col-md-4"><label class="form-check"><input class="form-check-input" type="checkbox" name="qualified_divisions[]" value="<?=$v?>"<?=checked('qualified_divisions',$v)?>> <span class="form-check-label"><?=$label?></span></label></div><?php endforeach;?></div></div><div class="col-md-6"><label class="form-label">Languages</label><input class="form-control" name="languages" value="<?=e((string)($_POST['languages']??''))?>" placeholder="e.g. English, Mandarin"></div><div class="col-12"><label class="form-label">Short biography</label><textarea class="form-control" name="biography" rows="3"><?=e((string)($_POST['biography']??''))?></textarea></div><div class="col-md-6"><label class="form-label">Judging experience</label><textarea class="form-control" name="experience" rows="3"><?=e((string)($_POST['experience']??''))?></textarea></div><div class="col-md-6"><label class="form-label">Certification or training</label><textarea class="form-control" name="certification" rows="3"><?=e((string)($_POST['certification']??''))?></textarea></div></div><div class="mt-4"><button class="btn btn-dark btn-lg">Submit Judge Profile</button></div></div></form></main></body></html>
